const express = require('express');
const Typesense = require('typesense');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

// Initialize Typesense Client
const client = new Typesense.Client({
  nodes: [{
    host: '127.0.0.1',
    port: '8108',
    protocol: 'http'
  }],
  apiKey: '4t04nBkkOjMn2xPMt30bNVMVU2AsK5Bt',
  connectionTimeoutSeconds: 5
});

// Function to initialize collection and index data
async function initTypesense() {
  const maxRetries = 15;
  const retryDelay = 1000;
  let healthy = false;

  for (let i = 0; i < maxRetries; i++) {
    try {
      const health = await client.health.retrieve();
      if (health.ok) {
        healthy = true;
        console.log('Typesense is healthy and ready!');
        break;
      }
    } catch (e) {
      console.log(`Waiting for Typesense server... (attempt ${i + 1}/${maxRetries})`);
      await new Promise(resolve => setTimeout(resolve, retryDelay));
    }
  }

  if (!healthy) {
    console.error('Could not connect to Typesense server. Exiting.');
    process.exit(1);
  }

  try {
    // Delete existing cities collection if it exists
    try {
      await client.collections('cities').delete();
      console.log('Deleted existing cities collection.');
    } catch (e) {
      // Ignore if not found
    }

    // Create cities collection schema
    const schema = {
      name: 'cities',
      fields: [
        { name: 'id', type: 'string' },
        { name: 'name', type: 'string', sort: true },
        { name: 'country', type: 'string' },
        { name: 'population', type: 'int32' }
      ],
      default_sorting_field: 'population'
    };

    await client.collections().create(schema);
    console.log('Created cities collection schema.');

    // Load city dataset
    const citiesPath = path.join(__dirname, 'data', 'cities.json');
    if (!fs.existsSync(citiesPath)) {
      console.error(`Cities dataset not found at ${citiesPath}`);
      process.exit(1);
    }

    const cities = JSON.parse(fs.readFileSync(citiesPath, 'utf8'));
    console.log(`Loaded ${cities.length} cities from dataset.`);

    // Import documents into Typesense
    await client.collections('cities').documents().import(cities, { action: 'create' });
    console.log('Successfully indexed cities dataset into Typesense.');

  } catch (error) {
    console.error('Failed to initialize and index Typesense:', error);
    process.exit(1);
  }
}

// GET / - Search Page
app.get('/', (req, res) => {
  res.send(`
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>City Search Autocomplete</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      max-width: 600px;
      margin: 60px auto;
      padding: 0 20px;
      color: #333;
    }
    h1 {
      text-align: center;
      margin-bottom: 30px;
      color: #111;
    }
    .search-container {
      position: relative;
    }
    #q {
      width: 100%;
      box-sizing: border-box;
      padding: 12px 16px;
      font-size: 16px;
      border: 2px solid #ccc;
      border-radius: 8px;
      outline: none;
      transition: border-color 0.2s;
    }
    #q:focus {
      border-color: #3b82f6;
    }
    #suggestions {
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background: white;
      border: 1px solid #ddd;
      border-top: none;
      border-radius: 0 0 8px 8px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      z-index: 1000;
      overflow: hidden;
    }
    .suggestion {
      padding: 12px 16px;
      font-size: 16px;
      cursor: pointer;
      border-bottom: 1px solid #f1f1f1;
      transition: background-color 0.1s;
    }
    .suggestion:last-child {
      border-bottom: none;
    }
    .suggestion:hover, .suggestion.active {
      background-color: #f3f4f6;
    }
    .suggestion.active {
      background-color: #3b82f6;
      color: white;
    }
    .suggestion.active mark {
      background-color: #fef08a;
      color: #000;
    }
    mark {
      background-color: #fef08a;
      font-weight: bold;
      border-radius: 2px;
      padding: 0 2px;
    }
  </style>
</head>
<body>
  <h1>City Search</h1>
  <div class="search-container">
    <input type="text" id="q" placeholder="Type a city name..." autocomplete="off">
    <div id="suggestions"></div>
  </div>

  <script>
    const input = document.getElementById('q');
    const container = document.getElementById('suggestions');
    let activeIndex = -1;

    function debounce(func, wait) {
      let timeout;
      const debounced = function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
      };
      debounced.cancel = function() {
        clearTimeout(timeout);
      };
      return debounced;
    }

    function escapeRegExp(str) {
      return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function highlight(name, query) {
      if (!query) return name;
      const tokens = query.trim().split(/\\s+/).filter(Boolean);
      if (tokens.length === 0) return name;

      const pattern = tokens.map(t => '\\\\b' + escapeRegExp(t)).join('|');
      const regex = new RegExp('(' + pattern + ')', 'gi');

      return name.replace(regex, '<mark>$1</mark>');
    }

    function clearSuggestions() {
      container.innerHTML = '';
      activeIndex = -1;
    }

    function updateActiveSuggestion(items) {
      items.forEach((item, index) => {
        if (index === activeIndex) {
          item.classList.add('active');
        } else {
          item.classList.remove('active');
        }
      });
    }

    function renderSuggestions(cities, query) {
      container.innerHTML = '';
      activeIndex = -1;

      if (cities.length === 0) {
        return;
      }

      cities.forEach((city, index) => {
        const div = document.createElement('div');
        div.className = 'suggestion';
        div.dataset.id = city.id;
        div.innerHTML = highlight(city.name, query);

        div.addEventListener('mouseenter', () => {
          const items = document.querySelectorAll('.suggestion');
          items.forEach(item => item.classList.remove('active'));
          div.classList.add('active');
          activeIndex = index;
        });

        div.addEventListener('click', () => {
          window.location.href = '/item/' + city.id;
        });

        container.appendChild(div);
      });
    }

    const debouncedFetch = debounce((query) => {
      if (!query.trim()) {
        clearSuggestions();
        return;
      }

      fetch('/api/suggest?q=' + encodeURIComponent(query))
        .then(res => res.json())
        .then(data => {
          renderSuggestions(data, query);
        })
        .catch(err => {
          console.error('Fetch error:', err);
        });
    }, 250);

    input.addEventListener('input', (e) => {
      const query = e.target.value;
      if (!query.trim()) {
        clearSuggestions();
        debouncedFetch.cancel();
      } else {
        debouncedFetch(query);
      }
    });

    input.addEventListener('keydown', (e) => {
      const items = document.querySelectorAll('.suggestion');
      if (items.length === 0) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (activeIndex === -1) {
          activeIndex = 0;
        } else {
          activeIndex = (activeIndex + 1) % items.length;
        }
        updateActiveSuggestion(items);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (activeIndex === -1) {
          activeIndex = items.length - 1;
        } else {
          activeIndex = (activeIndex - 1 + items.length) % items.length;
        }
        updateActiveSuggestion(items);
      } else if (e.key === 'Enter') {
        if (activeIndex !== -1) {
          e.preventDefault();
          const activeItem = items[activeIndex];
          const id = activeItem.dataset.id;
          window.location.href = '/item/' + id;
        }
      } else if (e.key === 'Escape') {
        e.preventDefault();
        clearSuggestions();
      }
    });

    document.addEventListener('click', (e) => {
      if (e.target !== input && !e.target.closest('#suggestions')) {
        clearSuggestions();
      }
    });
  </script>
</body>
</html>
  `);
});

// GET /api/suggest?q=<query>
app.get('/api/suggest', async (req, res) => {
  const q = req.query.q;
  if (!q || !q.trim()) {
    return res.json([]);
  }

  try {
    const searchParams = {
      q: q.trim(),
      query_by: 'name',
      sort_by: 'population:desc,name:asc',
      prefix: true,
      per_page: 8
    };

    const results = await client.collections('cities').documents().search(searchParams);

    // Map the results to exactly the required keys
    const suggestions = results.hits.map(hit => ({
      id: hit.document.id,
      name: hit.document.name,
      country: hit.document.country,
      population: hit.document.population
    }));

    // In-memory sorting as a fallback to guarantee perfect order
    suggestions.sort((a, b) => {
      if (b.population !== a.population) {
        return b.population - a.population;
      }
      return a.name.localeCompare(b.name);
    });

    // Limit to at most 8 suggestions
    const limitedSuggestions = suggestions.slice(0, 8);

    res.json(limitedSuggestions);
  } catch (error) {
    console.error('Search API error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

